AGENTS.md

# Benchmark workspace

- Work only in this repository. Do not read or modify parent directories.
- Do not use network access or install dependencies.
- Preserve exported names, behavior, and exact error text.
- Keep benchmark artifacts and the final handoff in English.
- Run `npm test` before claiming completion.

export function normalizeUser(record) {
  if (typeof record?.name !== 'string' || record.name.trim().length === 0) {
    throw new Error('Name is required.');
  }
  const name = record.name.trim();
  return {
    name,
    email: String(record.email ?? '').trim().toLowerCase(),
  };
}

export function normalizeAdmin(record) {
  if (typeof record?.name !== 'string' || record.name.trim().length === 0) {
    throw new Error('Name is required.');
  }
  const name = record.name.trim();
  return {
    name,
    email: String(record.email ?? '').trim(),
    permissions: [...(record.permissions ?? [])].sort(),
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { normalizeAdmin, normalizeUser } from '../src/normalizers.mjs';

test('keeps user normalization behavior', () => {
  assert.deepEqual(normalizeUser({ name: ' Ada ', email: ' ADA@EXAMPLE.COM ' }), {
    name: 'Ada',
    email: 'ada@example.com',
  });
});

test('keeps admin normalization behavior', () => {
  assert.deepEqual(normalizeAdmin({
    name: ' Root ',
    email: ' ROOT@EXAMPLE.COM ',
    permissions: ['write', 'read'],
  }), {
    name: 'Root',
    email: 'ROOT@EXAMPLE.COM',
    permissions: ['read', 'write'],
  });
});

test('keeps the exact validation error', () => {
  assert.throws(() => normalizeUser({ name: '   ' }), { message: 'Name is required.' });
  assert.throws(() => normalizeAdmin({ name: '' }), { message: 'Name is required.' });
});

